CREATE DATABASE IF NOT EXISTS kasir_warkop_djoeragan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kasir_warkop_djoeragan;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS transaction_detail_toppings; DROP TABLE IF EXISTS product_toppings; DROP TABLE IF EXISTS toppings; DROP TABLE IF EXISTS stock_movements; DROP TABLE IF EXISTS payments; DROP TABLE IF EXISTS transaction_details; DROP TABLE IF EXISTS transactions; DROP TABLE IF EXISTS products; DROP TABLE IF EXISTS categories; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,username VARCHAR(60) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('owner','kasir') NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,sku VARCHAR(50) NOT NULL UNIQUE,purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0,selling_price DECIMAL(14,2) NOT NULL,stock INT NOT NULL DEFAULT 0,min_stock INT NOT NULL DEFAULT 5,image VARCHAR(255) NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id) ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE toppings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,price DECIMAL(14,2) NOT NULL DEFAULT 0,is_available TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE product_toppings (product_id INT UNSIGNED NOT NULL,topping_id INT UNSIGNED NOT NULL,PRIMARY KEY(product_id,topping_id),CONSTRAINT fk_pt_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,CONSTRAINT fk_pt_topping FOREIGN KEY(topping_id) REFERENCES toppings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice VARCHAR(30) NOT NULL UNIQUE,cashier_id INT UNSIGNED NOT NULL,subtotal DECIMAL(14,2) NOT NULL,discount DECIMAL(14,2) NOT NULL DEFAULT 0,total DECIMAL(14,2) NOT NULL,profit DECIMAL(14,2) NOT NULL DEFAULT 0,order_name VARCHAR(100) NULL,table_number VARCHAR(30) NULL,status ENUM('open','paid','cancelled') NOT NULL DEFAULT 'paid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_transaction_cashier FOREIGN KEY(cashier_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE transaction_details (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,product_name VARCHAR(120) NOT NULL,price DECIMAL(14,2) NOT NULL,purchase_price DECIMAL(14,2) NOT NULL DEFAULT 0,quantity INT NOT NULL,subtotal DECIMAL(14,2) NOT NULL,CONSTRAINT fk_detail_transaction FOREIGN KEY(transaction_id) REFERENCES transactions(id) ON DELETE CASCADE,CONSTRAINT fk_detail_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
ALTER TABLE transaction_details ADD COLUMN note VARCHAR(255) NULL AFTER quantity;
CREATE TABLE transaction_detail_toppings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_detail_id BIGINT UNSIGNED NOT NULL,topping_id INT UNSIGNED NULL,topping_name VARCHAR(100) NOT NULL,price DECIMAL(14,2) NOT NULL DEFAULT 0,CONSTRAINT fk_tdt_detail FOREIGN KEY(transaction_detail_id) REFERENCES transaction_details(id) ON DELETE CASCADE,CONSTRAINT fk_tdt_topping FOREIGN KEY(topping_id) REFERENCES toppings(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL,method ENUM('tunai','qris','transfer','lainnya') NOT NULL,amount DECIMAL(14,2) NOT NULL,change_amount DECIMAL(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_payment_transaction FOREIGN KEY(transaction_id) REFERENCES transactions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE stock_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,type ENUM('in','out','sale','adjustment') NOT NULL,quantity INT NOT NULL,note VARCHAR(255),reference_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_stock_product FOREIGN KEY(product_id) REFERENCES products(id),CONSTRAINT fk_stock_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
